    $j = json_decode($b, true);
    if (!is_array($j)) { return $b; }
    foreach (['access_token', 'refresh_token', 'renewed_token', 'new_token', 'token', 'twitch_access_token'] as $k) {
        if (array_key_exists($k, $j)) { $j[$k . '_len'] = strlen((string) $j[$k]); unset($j[$k]); }
    }
    unset($j['cache']);
    return json_encode($j);
}
