    $custom[] = ['bot_username' => (string) $r['bot_username'], 'bot_channel_id' => (string) $r['bot_channel_id'], 'module' => true, 'verified' => (int) $r['is_verified'] === 1, 'has_token' => trim((string) $r['access_token']) !== '', 'expires' => $r['token_expires'] ?? '-'];
